"""Config service utility"""
from builtins import str
from builtins import object
import re
import json
from past.builtins import basestring
from robot.libraries.BuiltIn import BuiltIn
from taf.ul.trs_e2e_fw.lib.utils.exception.robot_exception import ConfigParamNotFoundException
from taf.ul.trs_e2e_fw.lib.utils.logger.robotbackgroundlogger import BackgroundLogger
from taf.rfrl.trs_e2e_fw.setup.config_handler import ConfigHandler

logger = BackgroundLogger.Instance()


class ServingClass(object):
    """Config service class"""
    # def replace_variables_in_config(self,dict_source=ConfigHandler.config):
    #     config_var = dict_source
    #     new_dict = {}
    #     for key, subconfig in config_var.items():
    #         new_dict[key] = self.replace_builtinvars(subconfig)
    #     logger.info(new_dict)
    #     return new_dict

    def get_config_variable(self, dict_path_list, dict_source=ConfigHandler.config):
        """
            This function returns the config variable value for the given dictionary path.
            Args:
                dict_path_list:
                dict_source:

            Returns:
        """
        config_var = dict_source
        # altered_dict = _replace_allbuiltinvars(dict_source=dict_source)
        if len(dict_path_list) == 0:
            return self.replace_all_variables_in_config(config_var)
        return self.get_config_variable_for_given_dictpath(config_var, dict_path_list)

    def get_config_variable_for_given_dictpath(self, config_var, dict_path_list):
        """Get config variable for given dictionary path"""
        try:
            for key in dict_path_list:
                config_var = config_var.get(key)
            config_var = self.replace_builtinvars(config_var)
            return config_var
        except AttributeError as error:
            pevious_key_not_found = dict_path_list[dict_path_list.index(key) - 1]
            raise ConfigParamNotFoundException(
                "Configuration parameter does not exist: {0}. Error: {1}".format(pevious_key_not_found, str(error)))
        finally:
            logger.debug("Config Var Path: {} Val: {}".format(str(dict_path_list), str(config_var)))

    def replace_all_variables_in_config(self, dict_source=ConfigHandler.config):
        """Replace all variables in config"""
        config_var = dict_source
        if isinstance(dict_source, list):
            new_list = []
            for subConfig in dict_source:
                new_list.append(self.replace_builtinvars(subConfig))
            return new_list
        elif isinstance(dict_source, dict):
            new_dict = {}
            for key, subconfig in list(config_var.items()):
                new_dict[key] = self.replace_builtinvars(subconfig)
            logger.info(new_dict)
            return new_dict
        else:
            new_var = self.replace_builtinvars(config_var)
            return new_var

    def replace_builtinvars(self, var):
        """Replace built-in variables"""
        if isinstance(var, list):
            return [self._replace_builtinvars_in_string(item) for item in var]
        elif isinstance(var, dict):
            return self._replace_builtinvars_in_dict(dict_source=var)
        else:
            return self._replace_builtinvars_in_string(var)

    def _replace_builtinvars_in_string(self, target_string):
        """
        Args:
            target_string:

        Returns:

        """
        if isinstance(target_string, basestring):
            pattern_object = re.compile(r"\$\{.*?\}")  # matches ${dscp} or {dscp} in the filter string
            return pattern_object.sub(self._get_string_to_replace, target_string)
        return target_string

    def _replace_builtinvars_in_dict(self, dict_source):
        altered_dict = {}
        for key, val in list(dict_source.items()):
            altered_dict[key] = self.replace_builtinvars(val)
            # if isinstance(val, list):
            #     altered_dict[key] = [replace_builtinvars_in_string(item) for item in val]
            # elif isinstance(val, dict):
            #     altered_dict[key] = _replace_builtinvars_in_dict(val)
            # else:
            #     altered_dict[key] = replace_builtinvars_in_string(val)
        return altered_dict

    def _get_string_to_replace(self, match_object):
        string_to_replace = match_object.group()
        value = BuiltIn().get_variable_value(string_to_replace)
        logger.debug("Variable type is {}".format(type(value)))
        if isinstance(value, (int, float)):
            logger.debug("Converting to string")
            value = str(value)
        return value

    def _get_config_variable_from_string(self, dict_path_list, dict_source=None):
        try:
            if dict_source is None:
                dict_value = ConfigHandler.config
            else:
                dict_value = dict_source
            for key in dict_path_list:
                dict_value = dict_value.get(key)
            logger.debug("Dict Value is {}".format(dict_value))
            input_json_string = json.dumps(dict_value)
            logger.debug("input_json_string is {}".format(input_json_string))
            replaced_json_string = self._replace_builtinvars_in_string(input_json_string)
            logger.debug("replaced_json_string is {}".format(replaced_json_string))
            return json.loads(replaced_json_string)
        except Exception as config_exception:
            raise ConfigParamNotFoundException("Configuration parameter does not exist: {0}. Error: {1}"
                                               .format(dict_value, str(config_exception)))

# def get_config_variable(dict_path_list, dict_source=ConfigHandler.config):
