obj = ServingClass()


def get_config_variable(dict_path_list, dict_source=ConfigHandler.config):
    """Get config variable"""
    return obj.get_config_variable(dict_path_list=dict_path_list, dict_source=dict_source)


def set_config_variable(config_path, value):
    """Set config variable"""
    config_dict = ConfigHandler.config
    for each_key in config_path:
        if isinstance(config_dict[each_key], dict):
            config_dict = config_dict[each_key]
    config_dict[config_path[-1]] = value
    # Multi-level value updating to be supported later


def replace_builtinvars(var):
    """Replace built-in variables"""
    return obj.replace_builtinvars(var=var)


def get_config_variable_from_string(dict_path_list, dict_source=None):
    """Get config variables from string"""
    return obj._get_config_variable_from_string(dict_path_list, dict_source)


def replace_all_variables(dict_source=ConfigHandler.config):
    """Replace al variables"""
    return obj.replace_all_variables_in_config(dict_source)
